1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.OwnerIdentity;
6	import org.springframework.samples.petclinic.model.Soundex;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Flags a soft duplicate: a create that shares an existing owner's surname Soundex and postcode
12	 * but carries a <em>different</em> {@link OwnerIdentity identity key} — i.e. a different
13	 * telephone or email. (An identical identity key is a hard duplicate and was already rejected
14	 * with a 409 by {@link RejectDuplicateOwnerIdentity}, so it never reaches here.) The owner is
15	 * still created; the response merely carries {@code possibleDuplicate}/{@code possibleDuplicateOf}
16	 * pointing at the matched owner.
17	 *
18	 * <p>A declared household member — one created with {@code sharesHousehold} — deliberately
19	 * shares an existing owner's surname and postcode, so it is <em>not</em> a suspected duplicate
20	 * and is left unflagged.
21	 *
22	 * <p>Runs after {@link BuildOwner} but before the owner is saved, so it compares against the
23	 * owners that existed before this create (and so never matches the owner being built), and
24	 * mutates the built {@link Owner} in place. When several owners match, the one with the lowest
25	 * id is reported, so the result is deterministic. Surnames are compared by their {@link Soundex}
26	 * code; postcode is compared in its stored, normalized form.
27	 */
28	public class AssignOwnerPossibleDuplicate {
29	
30	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return; // a declared household member is not a suspected duplicate
33	        }
34	        String postcode = trimmed(owner.getPostcode());
35	        if (postcode == null) {
36	            return; // no postcode to share, so no soft match
37	        }
38	        String soundex = Soundex.encode(owner.getLastName());
39	        String identityKey = OwnerIdentity.of(owner);
40	        Owner match = null;
41	        for (Owner existing : Owners.active(ownerRepository.findAll())) {
42	            if (soundex.equals(Soundex.encode(existing.getLastName()))
43	                    && postcode.equals(trimmed(existing.getPostcode()))
44	                    && !identityKey.equals(OwnerIdentity.of(existing))
45	                    && (match == null || existing.getId() < match.getId())) {
46	                match = existing;
47	            }
48	        }
49	        if (match != null) {
50	            owner.setPossibleDuplicateOf(match.getId());
51	        }
52	    }
53	
54	    private static String trimmed(String value) {
55	        if (value == null) {
56	            return null;
57	        }
58	        String trimmed = value.trim();
59	        return trimmed.isEmpty() ? null : trimmed;
60	    }
61	}
